  'profile.referralCode': ['REFERRAL CODE', 'MÃ GIỚI THIỆU', 'KODE REFERAL', 'रेफ़रल कोड', '推荐码', 'РЕФЕРАЛЬНЫЙ КОД', '紹介コード', 'CÓDIGO DE INDICAÇÃO', 'CÓDIGO DE REFERIDO'],
  'profile.copiedUpper': ['COPIED', 'ĐÃ CHÉP', 'DISALIN', 'कॉपी हुआ', '已复制', 'СКОПИРОВАНО', 'コピー済み', 'COPIADO', 'COPIADO'],
  'profile.dataDevice': ['Readings, GEM and history are tied to this device. Reinstalling or changing phones may lose them.', 'Bài bói, gems và lịch sử gắn với thiết bị này. Cài lại app hoặc đổi máy có thể mất dữ liệu.', 'Pembacaan, GEM, dan riwayat terikat ke perangkat ini. Instal ulang atau ganti ponsel dapat menghapusnya.', 'रीडिंग, GEM और इतिहास इस डिवाइस से जुड़े हैं। ऐप दोबारा इंस्टॉल करने या फ़ोन बदलने पर ये खो सकते हैं।', '解读、GEM 和历史记录与此设备绑定。重装应用或更换手机可能丢失数据。', 'Толкования, GEM и история привязаны к этому устройству. При переустановке или смене телефона они могут пропасть.', '鑑定、GEM、履歴はこの端末に紐づいています。再インストールや機種変更で失われる場合があります。', 'Leituras, GEM e histórico ficam neste dispositivo. Reinstalar ou trocar de celular pode apagá-los.', 'Las lecturas, GEM e historial están ligados a este dispositivo. Reinstalar o cambiar de móvil puede borrarlos.'],
  'profile.dataAccount': ['Readings, GEM and history are saved to your account.', 'Bài bói, gems và lịch sử được lưu cùng tài khoản của bạn.', 'Pembacaan, GEM, dan riwayat tersimpan di akun Anda.', 'रीडिंग, GEM और इतिहास आपके खाते में सहेजे जाते हैं।', '解读、GEM 和历史记录保存在你的账号中。', 'Толкования, GEM и история сохраняются в вашем аккаунте.', '鑑定、GEM、履歴はアカウントに保存されます。', 'Leituras, GEM e histórico ficam salvos na sua conta.', 'Las lecturas, GEM e historial se guardan en tu cuenta.'],
  'profile.vipMember': ['PalmSight VIP member', 'Hội viên VIP PalmSight', 'Anggota VIP PalmSight', 'PalmSight VIP सदस्य', 'PalmSight VIP 会员', 'Участник PalmSight VIP', 'PalmSight VIP メンバー', 'Membro VIP PalmSight', 'Miembro VIP de PalmSight'],
  'profile.vipUpgrade': ['Upgrade to VIP membership', 'Nâng cấp Hội Viên VIP', 'Tingkatkan ke keanggotaan VIP', 'VIP सदस्यता में अपग्रेड करें', '升级 VIP 会员', 'Оформить VIP-подписку', 'VIP メンバーにアップグレード', 'Fazer upgrade para VIP', 'Mejorar a membresía VIP'],
  'profile.vipActiveBody': ['Active: +50 GEM/day, all schools, no banner or interstitial ads', 'Đang hoạt động: +50 GEM/ngày, mở khoá mọi trường phái, không quảng cáo biểu ngữ & xen kẽ', 'Aktif: +50 GEM/hari, semua aliran, tanpa iklan banner atau interstisial', 'सक्रिय: +50 GEM/दिन, सभी परंपराएँ, कोई बैनर या इंटरस्टीशियल विज्ञापन नहीं', '已生效：每天 +50 GEM，解锁全部流派，无横幅和插页广告', 'Активно: +50 GEM в день, все школы, без баннерной и межстраничной рекламы', '有効：1 日 +50 GEM、全流派、バナー広告とインタースティシャル広告なし', 'Ativo: +50 GEM/dia, todas as escolas, sem anúncios de banner ou intersticiais', 'Activo: +50 GEM/día, todas las escuelas, sin anuncios de banner ni intersticiales'],
  'profile.vipOfferBody': ['50 GEM every day, Eastern & Vedic schools, no banner or interstitial ads', '50 GEM mỗi ngày, mở khoá trường phái Phương Đông & Vedic, không quảng cáo biểu ngữ & xen kẽ', '50 GEM setiap hari, aliran Timur & Veda, tanpa iklan banner atau interstisial', 'हर दिन 50 GEM, पूर्वी और वैदिक परंपराएँ, कोई बैनर या इंटरस्टीशियल विज्ञापन नहीं', '每天 50 GEM，东方与吠陀流派，无横幅和插页广告', '50 GEM каждый день, восточная и ведическая школы, без баннерной и межстраничной рекламы', '毎日 50 GEM、東洋とヴェーダの流派、バナー広告とインタースティシャル広告なし', '50 GEM por dia, escolas Oriental e Védica, sem anúncios de banner ou intersticiais', '50 GEM al día, escuelas Oriental y Védica, sin anuncios de banner ni intersticiales'],
  'profile.manageVip': ['Manage VIP plan', 'Quản lý gói VIP', 'Kelola paket VIP', 'VIP प्लान प्रबंधित करें', '管理 VIP 方案', 'Управлять VIP-планом', 'VIP プランを管理', 'Gerenciar plano VIP', 'Gestionar plan VIP'],
