  'reading.cannotOpen': ['CANNOT OPEN READING', 'KHÔNG MỞ ĐƯỢC QUẺ', 'TIDAK DAPAT MEMBUKA', 'रीडिंग नहीं खुली', '无法打开解读', 'НЕ УДАЛОСЬ ОТКРЫТЬ', '鑑定を開けません', 'NÃO FOI POSSÍVEL ABRIR', 'NO SE PUDO ABRIR'],
