  'reading.opening': ['YOUR PATH IS OPENING', 'THIÊN CƠ ĐANG MỞ', 'JALAN ANDA TERBUKA', 'आपका पथ खुल रहा है', '命途正在开启', 'ВАШ ПУТЬ ОТКРЫВАЕТСЯ', '運命がひらいています', 'SEU CAMINHO ESTÁ SE ABRINDO', 'TU CAMINO SE ESTÁ ABRIENDO'],
  'reading.processingTitle': ['Reading in progress', 'Đang luận giải quẻ', 'Pembacaan sedang diproses', 'रीडिंग जारी है', '正在解读', 'Идёт толкование', '鑑定中です', 'Leitura em andamento', 'Lectura en curso'],
  'reading.processingBody': ['The AI is reading your palm lines. This screen updates when the result is ready.', 'AI đang đọc các đường chỉ tay. Màn này sẽ tự cập nhật khi có kết quả.', 'AI sedang membaca garis tangan Anda. Layar ini diperbarui saat hasil siap.', 'AI आपकी हस्तरेखाएँ पढ़ रहा है। परिणाम मिलते ही यह स्क्रीन अपडेट होगी।', 'AI 正在解读你的掌纹，结果就绪后此页面会自动更新。', 'ИИ читает линии ладони. Экран обновится, когда результат будет готов.', 'AI が手相を読んでいます。結果が出るとこの画面は自動で更新されます。', 'A IA está lendo as linhas da sua mão. Esta tela atualiza quando o resultado estiver pronto.', 'La IA está leyendo las líneas de tu mano. Esta pantalla se actualizará cuando esté el resultado.'],
  'reading.toHistory': ['Go to History', 'Về Lịch sử', 'Ke Riwayat', 'इतिहास पर जाएँ', '前往历史记录', 'К истории', '履歴へ', 'Ir para o histórico', 'Ir al historial'],
  'reading.notDone': ['READING INCOMPLETE', 'QUẺ CHƯA THÀNH', 'PEMBACAAN BELUM SELESAI', 'रीडिंग अधूरी', '解读未完成', 'ТОЛКОВАНИЕ НЕ ЗАВЕРШЕНО', '鑑定未完了', 'LEITURA INCOMPLETA', 'LECTURA INCOMPLETA'],
  'reading.rejectedTitle': ['Could not see your palm clearly', 'Không nhìn rõ lòng bàn tay', 'Telapak tangan tidak terlihat jelas', 'हथेली साफ़ नहीं दिखी', '无法看清手掌', 'Ладонь видна нечётко', '手のひらがはっきり見えません', 'Não foi possível ver sua mão com clareza', 'No se ve bien tu mano'],
  'reading.busyTitle': ['The system is busy', 'Hệ thống bận', 'Sistem sedang sibuk', 'सिस्टम व्यस्त है', '系统繁忙', 'Система занята', 'システムが混み合っています', 'O sistema está ocupado', 'El sistema está ocupado'],
  'reading.rejectedBody': ['Retake in good light with your hand held straight.', 'Hãy chụp lại nơi đủ sáng, xoè thẳng bàn tay.', 'Ambil ulang di tempat terang dengan tangan terbuka lurus.', 'अच्छी रोशनी में हाथ सीधा फैलाकर दोबारा लें।', '请在光线充足处伸直手掌重新拍摄。', 'Переснимите при хорошем свете, выпрямив ладонь.', '明るい場所で手をまっすぐ広げて撮り直してください。', 'Tire de novo com boa luz e a mão reta.', 'Repite con buena luz y la mano recta.'],
  'reading.busyBody': ['PalmSight could not complete this reading. You can try again or delete it.', 'PalmSight chưa thể luận giải lần này. Bạn có thể thử lại hoặc xoá quẻ.', 'PalmSight belum dapat menyelesaikan pembacaan ini. Coba lagi atau hapus.', 'PalmSight यह रीडिंग पूरी नहीं कर सका। फिर कोशिश करें या इसे हटाएँ।', 'PalmSight 未能完成此次解读。你可以重试或删除。', 'PalmSight не смог выполнить толкование. Повторите или удалите его.', 'PalmSight はこの鑑定を完了できませんでした。再試行するか削除できます。', 'O PalmSight não concluiu esta leitura. Tente novamente ou exclua.', 'PalmSight no pudo completar esta lectura. Puedes reintentar o eliminarla.'],
